const text=p=>(p?.rich_text||[]).map(x=>x.text?.content||x.plain_text||'').join('');
function fakeState(){const rows=[],writes=[];const notion=async(path,method,body)=>{if(path.endsWith('/query'))return {results:rows.filter(r=>text(r.properties['Availability Key'])===body.filter.rich_text.equals),has_more:false};if(path==='/pages'&&method==='POST'){const row={id:'state-'+rows.length,properties:body.properties};rows.push(row);writes.push(body);return row}const row=rows.find(r=>path==='/pages/'+r.id);if(row&&method==='PATCH'){Object.assign(row.properties,body.properties);writes.push(body);return row}throw Error('Unexpected state request '+path)};return {rows,writes,notion}};module.exports={fakeState};
